// ── Auto-generated config structure ────────────────────────────────────────
public class NoteStyleConfig
{
    public int ConfigVersion { get; set; } = 3;  // Increment when format changes
    public bool AutoGenerated { get; set; }
    public string? SourceXml { get; set; }
    public bool ColorizeByLane { get; set; } = false;
    
    /// <summary>How to render hold end caps: "attached" (pixel-perfect), "separate" (legacy)</summary>
    public string HoldEndCapMode { get; set; } = "attached";
    
    public Dictionary<string, string> Notes { get; set; } = new();
    public Dictionary<string, ReceptorFrames> Receptors { get; set; } = new();
    public Dictionary<string, HoldFrames> Holds { get; set; } = new();
    
    /// <summary>List of frame names that were rotated in the original atlas</summary>
    public List<string> RotatedFrames { get; set; } = new();
    
    /// <summary>Rotation statistics for debugging</summary>
    public RotationStats? Stats { get; set; }
    
    public class ReceptorFrames
    {
        public string? Static { get; set; }
        public string? Press { get; set; }
        public string? Confirm { get; set; }
        public string? ConfirmHold { get; set; }
    }
    
    public class HoldFrames
    {
        public string? Piece { get; set; }
        public string? End { get; set; }
    }
    
    public class RotationStats
    {
        public int TotalFrames { get; set; }
        public int RotatedFrames { get; set; }
        public int UnrotatedFrames { get; set; }
    }
}

public class AtlasFrame
{
    public Texture2D Texture { get; set; } = null!;
    public Rectangle Source  { get; set; }
    public int OffsetX { get; set; }
    public int OffsetY { get; set; }
    public int FrameW  { get; set; }
    public int FrameH  { get; set; }
    /// <summary>Full frame name from XML (e.g. "confirmLeft0001")</summary>
    public string Name { get; set; } = "";
    /// <summary>True if the frame is rotated 90° clockwise in the atlas (Starling format)</summary>
    public bool Rotated { get; set; } = false;
}

public class TextureAtlas
{
    // Key = full frame name, value = frame data
    private readonly List<AtlasFrame> _allFrames = new();
    public Texture2D Texture { get; }
    
    // Store unrotated textures created from rotated frames
    private readonly List<Texture2D> _unrotatedTextures = new();

    public TextureAtlas(Texture2D texture, string xmlText)
    {
        Texture = texture;
        var doc = new XmlDocument();
        doc.LoadXml(xmlText);
        var root = doc.DocumentElement!;
        foreach (XmlNode node in root.ChildNodes)
        {
            if (node.Name != "SubTexture") continue;
            string name = node.Attributes!["name"]?.Value ?? "";
            int x  = ParseIntOrFloat(node.Attributes["x"]?.Value  ?? "0");
            int y  = ParseIntOrFloat(node.Attributes["y"]?.Value  ?? "0");
            int w  = ParseIntOrFloat(node.Attributes["width"]?.Value  ?? "0");
            int h  = ParseIntOrFloat(node.Attributes["height"]?.Value ?? "0");
            int fx = ParseIntOrFloat(node.Attributes["frameX"]?.Value ?? "0");
            int fy = ParseIntOrFloat(node.Attributes["frameY"]?.Value ?? "0");
            int fw = ParseIntOrFloat(node.Attributes["frameWidth"]?.Value  ?? w.ToString());
            int fh = ParseIntOrFloat(node.Attributes["frameHeight"]?.Value ?? h.ToString());
            bool rotated = node.Attributes["rotated"]?.Value == "true";

            AtlasFrame frame;
            
            if (rotated)
            {
                // Create an unrotated version of this frame
                frame = CreateUnrotatedFrame(texture, name, x, y, w, h, fx, fy, fw, fh);
            }
            else
            {
                // Normal frame
                frame = new AtlasFrame
                {
                    Texture = texture,
                    Source  = new Rectangle(x, y, w, h),
                    OffsetX = fx,
                    OffsetY = fy,
                    FrameW  = fw,
                    FrameH  = fh,
                    Name    = name,
                    Rotated = false,
                };
            }
            
            _allFrames.Add(frame);
        }
    }
    
    private AtlasFrame CreateUnrotatedFrame(Texture2D sourceTexture, string name, 
        int x, int y, int w, int h, int fx, int fy, int fw, int fh)
    {
        // Extract the rotated region from the atlas
        Color[] rotatedData = new Color[w * h];
        sourceTexture.GetData(0, new Rectangle(x, y, w, h), rotatedData, 0, rotatedData.Length);
        
        // Create new texture with swapped dimensions (h x w becomes w x h after rotation)
        int newWidth = h;
        int newHeight = w;
        Texture2D unrotatedTexture = new Texture2D(sourceTexture.GraphicsDevice, newWidth, newHeight);
        Color[] unrotatedData = new Color[newWidth * newHeight];
        
        // Rotate the pixels -90 degrees (counterclockwise) to restore original orientation
        // The atlas has the frame rotated +90 (clockwise), so we rotate -90 to undo it
        for (int srcY = 0; srcY < h; srcY++)
        {
            for (int srcX = 0; srcX < w; srcX++)
            {
                int srcIndex = srcY * w + srcX;
                // After -90 rotation: (x,y) -> (y, width-1-x)
                int dstX = srcY;
                int dstY = (w - 1) - srcX;
                int dstIndex = dstY * newWidth + dstX;
                unrotatedData[dstIndex] = rotatedData[srcIndex];
            }
        }
        
        unrotatedTexture.SetData(unrotatedData);
        _unrotatedTextures.Add(unrotatedTexture);
        
        // IMPORTANT: frameWidth/frameHeight in XML are already in correct orientation
        // They represent the ORIGINAL unrotated dimensions
        // Keep original dimensions without scaling
        
        return new AtlasFrame
        {
            Texture = unrotatedTexture,
            Source  = new Rectangle(0, 0, newWidth, newHeight),
            OffsetX = fx,  // Keep original offsets
            OffsetY = fy,
            FrameW  = fw,  // Use original frame dimensions
            FrameH  = fh,
            Name    = name,
            Rotated = false,
        };
    }

    /// <summary>Parse int or float string and round to int. Handles values like "-1.5" from Codename Engine XMLs.</summary>
    private static int ParseIntOrFloat(string value)
    {
        if (int.TryParse(value, out int intVal))
            return intVal;
        if (float.TryParse(value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float floatVal))
            return (int)Math.Round(floatVal);
        return 0;
    }

    /// <summary>Get all frames whose name starts with the given prefix, sorted by numeric suffix.</summary>
    public List<AtlasFrame> GetFrames(string prefix)
    {
        var result = new List<AtlasFrame>();
        foreach (var f in _allFrames)
            if (f.Name.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                result.Add(f);

        result.Sort((a, b) =>
        {
            // Extract trailing digits for sort
            int na = ExtractSuffix(a.Name, prefix.Length);
            int nb = ExtractSuffix(b.Name, prefix.Length);
            return na.CompareTo(nb);
        });
        return result;
    }

    public AtlasFrame? GetFirstFrame(string prefix)
    {
        var frames = GetFrames(prefix);
        return frames.Count > 0 ? frames[0] : null;
    }
    
    /// <summary>Get all frame names in this atlas (for generic fallback detection).</summary>
    public List<string> GetAllFrameNames()
    {
        var names = new List<string>();
        foreach (var f in _allFrames)
            names.Add(f.Name);
        return names;
    }

    private static int ExtractSuffix(string name, int prefixLen)
    {
        string suffix = name.Length > prefixLen ? name[prefixLen..] : "";
        return int.TryParse(suffix, out int v) ? v : 0;
    }
}

public class NoteStyle
{
    // Note arrow frames: [lane 0-3, skinType 0-3]
    // skinType: 0=normal, 1=damage, 2=instakill, 3=heal
    // If a skin doesn't define frames for a specific type, falls back to type 0.
    public AtlasFrame?[,] NoteFrames { get; } = new AtlasFrame?[4, 4];

    // Convenience: get the frame for a lane+skinType, falling back to type 0
    public AtlasFrame? GetNoteFrame(int lane, int skinType)
        => NoteFrames[lane, skinType] ?? NoteFrames[lane, 0];

    // Receptor frames: [lane][state]
    // state 0=static, 1=press, 2=confirm, 3=confirmHold
    public List<AtlasFrame>?[,] ReceptorFrames { get; } = new List<AtlasFrame>?[4, 4];

    // Hold rendering: can use either texture-based (8 columns) or atlas-based (individual frames)
    public Texture2D? HoldTexture  { get; set; }
    
    // Atlas-based hold frames (Codename Engine style): [lane 0-3]
    // If these are set, they take priority over HoldTexture column-based rendering
    public AtlasFrame?[] HoldPieceFrames { get; } = new AtlasFrame?[4];  // Repeating body
    public AtlasFrame?[] HoldEndFrames   { get; } = new AtlasFrame?[4];  // End cap
    
    // Hold Note Cover frames (FMM v1.1 style): [lane 0-3]
    // If these are set, they take HIGHEST priority (start/hold/end system)
    public AtlasFrame?[] HoldCoverStart { get; } = new AtlasFrame?[4];  // Start frame (head)
    public AtlasFrame?[] HoldCoverHold  { get; } = new AtlasFrame?[4];  // Middle repeating frame
    public AtlasFrame?[] HoldCoverEnd   { get; } = new AtlasFrame?[4];  // End frame (tail)
    
    // Flag to indicate this is a converted Codename Engine notestyle
    // When true, should use CodenameNoteRenderer for proper positioning
    public bool IsCodenameEngine { get; set; } = false;
    
    public float NoteScale         { get; set; } = 0.65f;
    public float ReceptorScale     { get; set; } = 0.65f;

    // Animation FPS for each receptor state: static, press, confirm, confirmHold
    // Can be overridden per-skin via skin.json: { "fps": [24, 24, 24, 24] }
    // Defaults match FNF standard (24 FPS for all states).
    public float[] StateFps { get; set; } = { 24f, 24f, 24f, 24f };
    
    // Colorize notes/receptors by lane (for grayscale textures that need tinting)
    // When true, multiplies texture color by lane color (purple, cyan, green, red)
    public bool ColorizeByLane { get; set; } = false;
    
    /// <summary>How to render hold end caps: "attached" (pixel-perfect), "separate" (legacy)</summary>
    public string HoldEndCapMode { get; set; } = "attached";

    // Tint colors for skin types 1-3 when no dedicated frame exists.
    // skin=1 (BAD/X) → red
    // skin=2 (GOOD/O) → cyan/blue
    // skin=3 (heal) → green
    public Microsoft.Xna.Framework.Color TintDamage    { get; set; } = new Microsoft.Xna.Framework.Color(255, 50,  50);   // skin=1: X → red
    public Microsoft.Xna.Framework.Color TintInstakill { get; set; } = new Microsoft.Xna.Framework.Color(0,   200, 255);  // skin=2: O → cyan
    public Microsoft.Xna.Framework.Color TintHeal      { get; set; } = new Microsoft.Xna.Framework.Color(0,   230, 80);   // skin=3: heal → green

    /// <summary>Returns the fallback tint for a given skin type (0=White, 1=damage, 2=instakill, 3=heal).</summary>
    public Microsoft.Xna.Framework.Color GetSkinTint(int skinType) => skinType switch
    {
        1 => TintDamage,
        2 => TintInstakill,
        3 => TintHeal,
        _ => Microsoft.Xna.Framework.Color.White,
    };

    private static readonly string[] Directions = { "Left", "Down", "Up", "Right" };

    /// <summary>
    /// Determines if a note style folder should use the config.json system.
    /// Only use config for simple Codename Engine folders (1 PNG + 1 XML only).
    /// FMM folders with multiple files (NOTE_assets.png, NOTE_hold.png, etc.) use the old system.
    /// </summary>
    private static bool ShouldUseConfigSystem(string folderPath)
    {
        try
        {
            var files = Directory.GetFiles(folderPath, "*.*", SearchOption.TopDirectoryOnly);
            
            // Count PNG and XML files
            int pngCount = files.Count(f => f.EndsWith(".png", StringComparison.OrdinalIgnoreCase));
            int xmlCount = files.Count(f => f.EndsWith(".xml", StringComparison.OrdinalIgnoreCase));
            
            // Only use config system if there's exactly 1 PNG and 1 XML (Codename Engine style)
            // This excludes FMM/VSlice folders with NOTE_assets.png, NOTE_hold.png, etc.
            bool isSimpleFolder = (pngCount == 1 && xmlCount == 1);
            
            if (isSimpleFolder)
                Console.WriteLine($"[NoteStyle] Simple Codename Engine folder detected, using config.json system");
            else
                Console.WriteLine($"[NoteStyle] Multi-file folder detected ({pngCount} PNGs, {xmlCount} XMLs), using legacy system");
            
            return isSimpleFolder;
        }
        catch
        {
            return false;
        }
    }

    public static NoteStyle? Load(string assetsRoot, GraphicsDevice gd)
    {
        return LoadFromFolder(assetsRoot, gd);
    }

    /// <summary>
    /// Auto-detects frame mappings from XML and generates config.json if it doesn't exist.
    /// Returns the config, or null if auto-detection failed.
    /// </summary>
    private static NoteStyleConfig? AutoDetectAndGenerateConfig(string folderPath, string xmlPath)
    {
        const int CURRENT_CONFIG_VERSION = 3;
        
        try
        {
            string configPath = Path.Combine(folderPath, "config.json");
            
            // If config already exists, check version
            if (File.Exists(configPath))
            {
                try
                {
                    string json = File.ReadAllText(configPath);
                    var loadedConfig = System.Text.Json.JsonSerializer.Deserialize<NoteStyleConfig>(json, 
                        new System.Text.Json.JsonSerializerOptions { PropertyNameCaseInsensitive = true });
                    
                    // If version matches and config is valid, use it
                    if (loadedConfig != null && loadedConfig.ConfigVersion == CURRENT_CONFIG_VERSION)
                    {
                        Console.WriteLine($"[NoteStyle] Loaded existing config v{loadedConfig.ConfigVersion}: {configPath}");
                        return loadedConfig;
                    }
                    
                    // Otherwise, delete old config and regenerate
                    if (loadedConfig != null)
                    {
                        Console.WriteLine($"[NoteStyle] Config version mismatch (v{loadedConfig.ConfigVersion} -> v{CURRENT_CONFIG_VERSION}), regenerating...");
                        File.Delete(configPath);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"[NoteStyle] Failed to load config.json, regenerating: {ex.Message}");
                    File.Delete(configPath);
                }
            }

            // Parse XML to get all frame names and rotation info
            var xmlText = File.ReadAllText(xmlPath);
            var doc = new XmlDocument();
            doc.LoadXml(xmlText);
            var root = doc.DocumentElement!;
            
            var allFrameNames = new List<string>();
            var rotatedFrameNames = new List<string>();
            int totalFrames = 0;
            
            foreach (XmlNode node in root.ChildNodes)
            {
                if (node.Name == "SubTexture")
                {
                    string? name = node.Attributes?["name"]?.Value;
                    if (!string.IsNullOrEmpty(name))
                    {
                        allFrameNames.Add(name);
                        totalFrames++;
                        
                        // Check if frame is rotated
                        bool isRotated = node.Attributes?["rotated"]?.Value == "true";
                        if (isRotated)
                        {
                            rotatedFrameNames.Add(name);
                        }
                    }
                }
            }

            Console.WriteLine($"[NoteStyle] Auto-detecting frames from {Path.GetFileName(xmlPath)} ({allFrameNames.Count} frames found, {rotatedFrameNames.Count} rotated)");

            var config = new NoteStyleConfig
            {
                ConfigVersion = CURRENT_CONFIG_VERSION,
                AutoGenerated = true,
                SourceXml = Path.GetFileName(xmlPath),
                RotatedFrames = rotatedFrameNames,
                Stats = new NoteStyleConfig.RotationStats
                {
                    TotalFrames = totalFrames,
                    RotatedFrames = rotatedFrameNames.Count,
                    UnrotatedFrames = totalFrames - rotatedFrameNames.Count
                }
            };

            // ── Detect notes (static arrows) ──────────────────────────────────
            string[] directions = { "left", "down", "up", "right" };
            string[] directionsCaps = { "Left", "Down", "Up", "Right" };
            string[] colors = { "purple", "blue", "green", "red" }; // Codename Engine colors
            
            for (int i = 0; i < 4; i++)
            {
                string dir = directions[i];
                string dirCap = directionsCaps[i];
                string color = colors[i];
                
                // Try multiple patterns for note arrows
                // PRIORITY: Prefer color names (purple/blue/green/red) over arrow names
                // because arrow names are often grayscale outlines
                string? noteFrame = FindFirstMatch(allFrameNames, 
                    $"{color}0",           // purple0, blue0, etc. (FIRST PRIORITY - colored versions)
                    $"{color}",            // purple, blue, etc.
                    $"note{dirCap}0",      // noteLeft0
                    $"note{dirCap}",       // noteLeft
                    $"arrow{dirCap.ToUpper()}",  // arrowLEFT (often grayscale - LAST PRIORITY)
                    $"arrow{dirCap}"       // arrowLeft
                );
                
                if (noteFrame != null)
                {
                    config.Notes[dir] = noteFrame;
                }
            }
            
            // ColorizeByLane defaults to FALSE (use PNG colors as-is)
            // User can enable it manually in skin.json: { "colorizeByLane": true }
            config.ColorizeByLane = false;

            // ── Detect receptors (static, press, confirm) ─────────────────────
            for (int i = 0; i < 4; i++)
            {
                string dir = directions[i];
                string dirCap = directionsCaps[i];
                
                var receptor = new NoteStyleConfig.ReceptorFrames();
                
                // Static
                receptor.Static = FindFirstMatch(allFrameNames,
                    $"static{dirCap}",     // staticLeft
                    $"{dir} static",       // left static
                    $"arrow{dirCap.ToUpper()}",  // arrowLEFT (Codename fallback)
                    config.Notes.GetValueOrDefault(dir)  // Use note frame as fallback
                );
                
                // Press
                receptor.Press = FindFirstMatch(allFrameNames,
                    $"press{dirCap}",      // pressLeft
                    $"{dir} press"         // left press
                );
                
                // Confirm
                receptor.Confirm = FindFirstMatch(allFrameNames,
                    $"confirm{dirCap}",    // confirmLeft
                    $"{dir} confirm"       // left confirm
                );
                
                // ConfirmHold (optional, fallback to confirm)
                receptor.ConfirmHold = FindFirstMatch(allFrameNames,
                    $"confirmHold{dirCap}",
                    $"{dir} confirmhold",
                    receptor.Confirm  // Fallback to confirm
                );
                
                config.Receptors[dir] = receptor;
            }

            // ── Detect holds (piece and end) ──────────────────────────────────
            for (int i = 0; i < 4; i++)
            {
                string dir = directions[i];
                string color = colors[i];
                
                var hold = new NoteStyleConfig.HoldFrames();
                
                // Hold piece
                hold.Piece = FindFirstMatch(allFrameNames,
                    $"{color} hold piece",   // purple hold piece
                    $"{color}holdpiece",     // purpleholdpiece
                    $"{color} hold",         // purple hold
                    $"{dir} hold piece",
                    $"{dir}holdpiece"
                );
                
                // Hold end
                hold.End = FindFirstMatch(allFrameNames,
                    $"{color} hold end",     // purple hold end
                    $"{color}holdend",       // purpleholdend
                    $"{color} end hold",     // purple end hold (FUNKSCAPE order)
                    i == 0 ? "pruple end hold" : null,  // Typo fix for purple
                    $"{dir} hold end",
                    $"{dir}holdend"
                );
                
                config.Holds[dir] = hold;
            }

            // ── Save config.json ───────────────────────────────────────────────
            try
            {
                var options = new System.Text.Json.JsonSerializerOptions 
                { 
                    WriteIndented = true,
                    PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase
                };
                string json = System.Text.Json.JsonSerializer.Serialize(config, options);
                File.WriteAllText(configPath, json);
                Console.WriteLine($"[NoteStyle] Auto-generated config saved: {configPath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[NoteStyle] Failed to save config.json: {ex.Message}");
            }

            return config;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[NoteStyle] Auto-detection failed: {ex.Message}");
            return null;
        }
    }

    /// <summary>
    /// Finds the first frame name that starts with any of the given prefixes (case-insensitive).
    /// Returns null if none found.
    /// </summary>
    private static string? FindFirstMatch(List<string> frameNames, params string?[] prefixes)
    {
        foreach (var prefix in prefixes)
        {
            if (string.IsNullOrEmpty(prefix)) continue;
            
            foreach (var frameName in frameNames)
            {
                if (frameName.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                    return frameName;
            }
        }
        return null;
    }
    
    /// <summary>
    /// Intelligent arrow detection: analyzes ALL frame names and detects which are the 4 base arrows
    /// by looking for direction keywords (left/down/up/right, colors, etc.) and filtering out
    /// receptor/hold variants (press, confirm, hold, etc.)
    /// Returns array of 4 frame names: [left, down, up, right] or nulls if not found
    /// </summary>
    private static string?[] DetectArrowFrames(List<string> allFrameNames)
    {
        Console.WriteLine($"[NoteStyle] Starting intelligent arrow detection from {allFrameNames.Count} frames...");
        
        var result = new string?[4]; // [left, down, up, right]
        
        // Keywords for each direction (order matters: most specific first)
        var directionKeywords = new[] {
            new[] { "left", "izquierda", "izq", "purple", "morado", "←" },      // LEFT (0)
            new[] { "down", "abajo", "blue", "cyan", "azul", "↓" },             // DOWN (1)
            new[] { "up", "arriba", "green", "verde", "↑" },                    // UP (2)
            new[] { "right", "derecha", "der", "red", "rojo", "→" }             // RIGHT (3)
        };
        
        // Exclude patterns (these are NOT base arrows)
        var excludeKeywords = new[] { "press", "confirm", "hold", "end", "piece", "static" };
        
        for (int dir = 0; dir < 4; dir++)
        {
            // Find first frame that:
            // 1. Contains at least one direction keyword
            // 2. Does NOT contain any exclude keyword
            // 3. Preferably ends with "0000" or just "0" (base frame)
            
            string? bestMatch = null;
            int bestScore = -1;
            
            foreach (var frameName in allFrameNames)
            {
                string lowerName = frameName.ToLower();
                
                // Check if it contains any exclude keyword
                bool isExcluded = false;
                foreach (var exclude in excludeKeywords)
                {
                    if (lowerName.Contains(exclude))
                    {
                        isExcluded = true;
                        break;
                    }
                }
                
                if (isExcluded) continue;
                
                // Check if it contains any direction keyword for this direction
                bool matchesDirection = false;
                foreach (var keyword in directionKeywords[dir])
                {
                    if (lowerName.Contains(keyword))
                    {
                        matchesDirection = true;
                        break;
                    }
                }
                
                if (!matchesDirection) continue;
                
                // Calculate score (prefer frames ending with 0000 or 0)
                int score = 0;
                if (frameName.EndsWith("0000")) score = 3;
                else if (frameName.EndsWith("000")) score = 2;
                else if (frameName.EndsWith("0")) score = 1;
                
                // Prefer shorter names (more likely to be base frame)
                score += (100 - frameName.Length);
                
                if (score > bestScore)
                {
                    bestScore = score;
                    bestMatch = frameName;
                }
            }
            
            if (bestMatch != null)
            {
                result[dir] = bestMatch;
                Console.WriteLine($"[NoteStyle] Detected {new[]{"LEFT","DOWN","UP","RIGHT"}[dir]} arrow: '{bestMatch}'");
            }
        }
        
        int found = result.Count(f => f != null);
        Console.WriteLine($"[NoteStyle] Intelligent detection found {found}/4 arrows");
        
        return result;
    }
    
    /// <summary>
    /// Detects receptor frames (press/confirm states) for each direction
    /// Returns: [lane][state] where state: 0=static, 1=press, 2=confirm
    /// </summary>
    private static string?[,] DetectReceptorFrames(List<string> allFrameNames)
    {
        Console.WriteLine($"[NoteStyle] Detecting receptor frames...");
        
        var result = new string?[4, 3]; // [4 lanes][3 states: static, press, confirm]
        
        var directionKeywords = new[] {
            new[] { "left", "izquierda", "izq", "purple", "morado" },
            new[] { "down", "abajo", "blue", "cyan", "azul" },
            new[] { "up", "arriba", "green", "verde" },
            new[] { "right", "derecha", "der", "red", "rojo" }
        };
        
        var stateKeywords = new[] {
            new[] { "static" },           // Static (0)
            new[] { "press" },            // Press (1)
            new[] { "confirm" }           // Confirm (2)
        };
        
        for (int lane = 0; lane < 4; lane++)
        {
            for (int state = 0; state < 3; state++)
            {
                foreach (var frameName in allFrameNames)
                {
                    string lowerName = frameName.ToLower();
                    
                    // Must contain direction keyword
                    bool hasDirection = false;
                    foreach (var keyword in directionKeywords[lane])
                    {
                        if (lowerName.Contains(keyword))
                        {
                            hasDirection = true;
                            break;
                        }
                    }
                    
                    if (!hasDirection) continue;
                    
                    // Must contain state keyword
                    bool hasState = false;
                    foreach (var keyword in stateKeywords[state])
                    {
                        if (lowerName.Contains(keyword))
                        {
                            hasState = true;
                            break;
                        }
                    }
                    
                    if (!hasState) continue;
                    
                    // Don't include hold frames
                    if (lowerName.Contains("hold") || lowerName.Contains("end") || lowerName.Contains("piece"))
                        continue;
                    
                    // Found a match!
                    result[lane, state] = frameName;
                    Console.WriteLine($"[NoteStyle] Detected receptor: lane={lane}, state={new[]{"static","press","confirm"}[state]}, frame='{frameName}'");
                    break; // Take first match
                }
            }
        }
        
        return result;
    }

    /// <summary>
    /// Loads a note style from a specific folder.
    /// First tries to load from config.json (auto-generated or manual).
    /// If config doesn't exist, auto-detects and generates it.
    /// Falls back to assetsRoot default if the custom folder is missing files.
    /// </summary>
    public static NoteStyle? LoadFromFolder(string folderPath, GraphicsDevice gd)
    {
        try
        {
            var style = new NoteStyle();

            // ── Find note arrows PNG+XML ──────────────────────────────────────
            string? notePng = null, noteXml = null;
            string[] noteCandidates = { "fmm.png", "notes.png", "NOTE_assets.png", "default.png", "sonic.png" };
            foreach (var c in noteCandidates)
            {
                string p = Path.Combine(folderPath, c);
                string x = Path.ChangeExtension(p, ".xml");
                if (File.Exists(p) && File.Exists(x)) { notePng = p; noteXml = x; break; }
            }
            // Also check shared/images subfolder (VSlice layout)
            if (notePng == null)
            {
                string p = Path.Combine(folderPath, "shared", "images", "fmm.png");
                string x = Path.ChangeExtension(p, ".xml");
                if (File.Exists(p) && File.Exists(x)) { notePng = p; noteXml = x; }
            }
            
            // NEW: If still not found, search for ANY PNG+XML pair in the folder
            if (notePng == null)
            {
                try
                {
                    var pngFiles = Directory.GetFiles(folderPath, "*.png", SearchOption.TopDirectoryOnly);
                    foreach (var png in pngFiles)
                    {
                        string xml = Path.ChangeExtension(png, ".xml");
                        if (File.Exists(xml))
                        {
                            notePng = png;
                            noteXml = xml;
                            Console.WriteLine($"[NoteStyle] Auto-detected note files: {Path.GetFileName(png)} + {Path.GetFileName(xml)}");
                            break;
                        }
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"[NoteStyle] Error searching for PNG+XML files: {ex.Message}");
                }
            }
            
            if (notePng == null) return null;

            Texture2D noteTex;
            using (var fs = File.OpenRead(notePng))
                noteTex = Texture2D.FromStream(gd, fs);
            
            // Read and potentially convert the XML if it's a unified format (Codename Engine style)
            string xmlContent = File.ReadAllText(noteXml!);
            var noteAtlas = new TextureAtlas(noteTex, xmlContent);
            
            // Check if this is a unified XML containing both notes and receptors (Codename/Haunted style)
            bool isUnifiedXML = DetectUnifiedXML(xmlContent);
            
            // Check if this is Codename Engine style (has hold frames that need conversion)
            bool isCodenameEngine = xmlContent.Contains("hold piece") || xmlContent.Contains("hold end");
            
            Console.WriteLine($"[NoteStyle] ═══════════════════════════════════════════");
            Console.WriteLine($"[NoteStyle] XML contains 'hold piece': {xmlContent.Contains("hold piece")}");
            Console.WriteLine($"[NoteStyle] XML contains 'hold end': {xmlContent.Contains("hold end")}");
            Console.WriteLine($"[NoteStyle] isCodenameEngine: {isCodenameEngine}");
            
            // Mark Codename Engine format for renderer selection
            if (isCodenameEngine)
            {
                Console.WriteLine($"[NoteStyle] ✓ CODENAME ENGINE FORMAT DETECTED");
                style.IsCodenameEngine = true;
                Console.WriteLine($"[NoteStyle] ✓ Marked as IsCodenameEngine = true");
            }
            Console.WriteLine($"[NoteStyle] ═══════════════════════════════════════════");

            // ── Try to load from config.json (or auto-generate it) ────────────
            // Only use config.json for simple Codename Engine folders (just 1 PNG + 1 XML)
            var config = ShouldUseConfigSystem(folderPath) && !string.IsNullOrEmpty(noteXml)
                ? AutoDetectAndGenerateConfig(folderPath, noteXml) 
                : null;
            
            // UNIVERSAL: Count how many frames were found for diagnostics
            int foundFrames = 0;
            
            if (config != null)
            {
                // Load using config mappings
                Console.WriteLine($"[NoteStyle] Loading with config mappings");
                string[] dirs = { "left", "down", "up", "right" };
                
                for (int i = 0; i < 4; i++)
                {
                    string dir = dirs[i];
                    
                    // Load note frames
                    if (config.Notes.TryGetValue(dir, out string? noteFrame))
                    {
                        style.NoteFrames[i, 0] = noteAtlas.GetFirstFrame(noteFrame);
                        if (style.NoteFrames[i, 0] != null) foundFrames++;
                    }
                }
            }
            else
            {
                // Fallback to old detection method
                Console.WriteLine($"[NoteStyle] Config failed, using fallback detection");
                string[] notePrefixes = { "noteLeft", "noteDown", "noteUp", "noteRight" };
                string[] codenamePrefixes = { "arrowLEFT", "arrowDOWN", "arrowUP", "arrowRIGHT" };
                string[] colorPrefixes = { "purple", "blue", "green", "red" };
                
                for (int i = 0; i < 4; i++)
                {
                    style.NoteFrames[i, 0] = noteAtlas.GetFirstFrame(notePrefixes[i] + "0")
                                          ?? noteAtlas.GetFirstFrame(notePrefixes[i])
                                          ?? noteAtlas.GetFirstFrame(codenamePrefixes[i])
                                          ?? noteAtlas.GetFirstFrame(colorPrefixes[i]);
                    
                    if (style.NoteFrames[i, 0] != null) foundFrames++;
                }
            }
            
            // UNIVERSAL FALLBACK: If no frames found with standard names, use generic fallback
            // This handles custom XMLs with non-standard frame names (works for both config and non-config)
            if (foundFrames == 0)
            {
                Console.WriteLine($"[NoteStyle] No standard frame names found, trying intelligent arrow detection...");
                
                // Get all frame names from the atlas
                var allFrames = noteAtlas.GetAllFrameNames();
                if (allFrames != null && allFrames.Count > 0)
                {
                    Console.WriteLine($"[NoteStyle] Found {allFrames.Count} frames in XML");
                    
                    // Try intelligent detection first (looks for left/down/up/right keywords)
                    var detectedArrows = DetectArrowFrames(allFrames);
                    for (int i = 0; i < 4; i++)
                    {
                        if (detectedArrows[i] != null)
                        {
                            style.NoteFrames[i, 0] = noteAtlas.GetFirstFrame(detectedArrows[i]!);
                            if (style.NoteFrames[i, 0] != null)
                                foundFrames++;
                        }
                    }
                    
                    // If intelligent detection failed, fall back to cyclical assignment
                    if (foundFrames == 0)
                    {
                        Console.WriteLine($"[NoteStyle] Intelligent detection failed, using cyclical assignment...");
                        Console.WriteLine($"[NoteStyle] First 10 frames: {string.Join(", ", allFrames.Take(10))}");
                        
                        for (int i = 0; i < 4 && i < allFrames.Count; i++)
                        {
                            style.NoteFrames[i, 0] = noteAtlas.GetFirstFrame(allFrames[i]);
                            if (style.NoteFrames[i, 0] != null)
                            {
                                Console.WriteLine($"[NoteStyle] Assigned frame '{allFrames[i]}' to direction {i} (left=0, down=1, up=2, right=3)");
                                foundFrames++;
                            }
                        }
                    }
                }
            }
            
            Console.WriteLine($"[NoteStyle] Loaded {foundFrames}/4 note frames");
            
            // skinType 1 = damage, 2 = instakill, 3 = heal (always use fallback detection)
            string[] notePrefixesSkin = { "noteLeft", "noteDown", "noteUp", "noteRight" };
            for (int i = 0; i < 4; i++)
            {
                for (int st = 1; st <= 3; st++)
                    style.NoteFrames[i, st] = noteAtlas.GetFirstFrame(notePrefixesSkin[i] + st.ToString());
            }

            // ── Find receptor PNG+XML ─────────────────────────────────────────
            string? recPng = null, recXml = null;
            
            // If we detected a unified XML, use the same atlas for receptors
            if (isUnifiedXML)
            {
                Console.WriteLine($"[NoteStyle] Detected unified XML format (Codename/Haunted style) - using same atlas for receptors");
                recPng = notePng;
                recXml = noteXml;
            }
            else
            {
                // Priority: notefmm.png > noteStrumline.png > NOTE_assets.png > default.png (if different from notes)
                string[] recCandidates = { "notefmm.png", "noteStrumline.png", "NOTE_assets.png", "default.png" };
                foreach (var c in recCandidates)
                {
                    string p = Path.Combine(folderPath, c);
                    string x = Path.ChangeExtension(p, ".xml");
                    if (File.Exists(p) && File.Exists(x) && p != notePng) { recPng = p; recXml = x; break; }
                }
                // Also check shared/images subfolder
                if (recPng == null)
                {
                    string p = Path.Combine(folderPath, "shared", "images", "notefmm.png");
                    string x = Path.ChangeExtension(p, ".xml");
                    if (File.Exists(p) && File.Exists(x)) { recPng = p; recXml = x; }
                }
                
                // NEW: If still not found, search for any OTHER PNG+XML pair (different from notes)
                if (recPng == null)
                {
                    try
                    {
                        var pngFiles = Directory.GetFiles(folderPath, "*.png", SearchOption.TopDirectoryOnly);
                        foreach (var png in pngFiles)
                        {
                            string xml = Path.ChangeExtension(png, ".xml");
                            if (File.Exists(xml) && png != notePng)
                            {
                                recPng = png;
                                recXml = xml;
                                Console.WriteLine($"[NoteStyle] Auto-detected receptor files: {Path.GetFileName(png)} + {Path.GetFileName(xml)}");
                                break;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"[NoteStyle] Error searching for receptor PNG+XML files: {ex.Message}");
                    }
                }
                
                // If still not found, try using the same atlas as notes (some skins combine both)
                if (recPng == null) { recPng = notePng; recXml = noteXml; }
            }

            Texture2D recTex;
            using (var fs = File.OpenRead(recPng!))
                recTex = recPng == notePng ? noteTex : Texture2D.FromStream(gd, fs);
            var recAtlas = recPng == notePng ? noteAtlas : new TextureAtlas(recTex, File.ReadAllText(recXml!));

            // ── Load receptors (use config if available) ──────────────────────
            int foundReceptorFrames = 0;
            
            if (config != null)
            {
                string[] dirs = { "left", "down", "up", "right" };
                for (int lane = 0; lane < 4; lane++)
                {
                    string dir = dirs[lane];
                    if (!config.Receptors.TryGetValue(dir, out var receptor)) continue;
                    
                    // Static
                    if (!string.IsNullOrEmpty(receptor.Static))
                    {
                        var frames = recAtlas.GetFrames(receptor.Static);
                        style.ReceptorFrames[lane, 0] = frames.Count > 0 ? frames : null;
                        if (frames.Count > 0) foundReceptorFrames++;
                    }
                    
                    // Press
                    if (!string.IsNullOrEmpty(receptor.Press))
                    {
                        var frames = recAtlas.GetFrames(receptor.Press);
                        style.ReceptorFrames[lane, 1] = frames.Count > 0 ? frames : null;
                    }
                    
                    // Confirm
                    if (!string.IsNullOrEmpty(receptor.Confirm))
                    {
                        var frames = recAtlas.GetFrames(receptor.Confirm);
                        style.ReceptorFrames[lane, 2] = frames.Count > 0 ? frames : null;
                    }
                    
                    // ConfirmHold
                    if (!string.IsNullOrEmpty(receptor.ConfirmHold))
                    {
                        var frames = recAtlas.GetFrames(receptor.ConfirmHold);
                        style.ReceptorFrames[lane, 3] = frames.Count > 0 ? frames : null;
                    }
                    else if (style.ReceptorFrames[lane, 2] != null)
                    {
                        // Fallback to confirm frames
                        style.ReceptorFrames[lane, 3] = style.ReceptorFrames[lane, 2];
                    }
                }
            }
            else
            {
                // Fallback detection
                for (int lane = 0; lane < 4; lane++)
                {
                    string dir = Directions[lane];
                    string[] prefixes = { "static" + dir, "press" + dir, "confirm" + dir, "confirmHold" + dir };
                    string[] cnPrefixes = { dir.ToLower() + " static", dir.ToLower() + " press", dir.ToLower() + " confirm", dir.ToLower() + " confirm" };
                    
                    for (int state = 0; state < 4; state++)
                    {
                        var frames = recAtlas.GetFrames(prefixes[state]);
                        if (frames.Count == 0)
                            frames = recAtlas.GetFrames(cnPrefixes[state]);
                        
                        if (frames.Count == 0 && state == 3)
                        {
                            frames = recAtlas.GetFrames("confirm" + dir);
                            if (frames.Count == 0)
                                frames = recAtlas.GetFrames(dir.ToLower() + " confirm");
                        }
                        
                        if (frames.Count == 0 && state == 0)
                        {
                            var arrowFrames = recAtlas.GetFrames("arrow" + dir.ToUpper());
                            if (arrowFrames.Count > 0)
                                frames = arrowFrames;
                            else if (style.NoteFrames[lane, 0] != null)
                                frames = new List<AtlasFrame> { style.NoteFrames[lane, 0]! };
                        }
                        
                        style.ReceptorFrames[lane, state] = frames.Count > 0 ? frames : null;
                        if (state == 0 && frames.Count > 0) foundReceptorFrames++;
                    }
                }
            }
            
            // UNIVERSAL FALLBACK: If no receptor frames found, use note frames (static receptors)
            // This handles skins where NOTE_assets.png contains both notes and receptors with the same frames
            if (foundReceptorFrames == 0)
            {
                Console.WriteLine($"[NoteStyle] No receptor frames found, using note frames as fallback");
                for (int lane = 0; lane < 4; lane++)
                {
                    if (style.NoteFrames[lane, 0] != null)
                    {
                        // Use note frame for static receptor (state 0)
                        style.ReceptorFrames[lane, 0] = new List<AtlasFrame> { style.NoteFrames[lane, 0]! };
                        foundReceptorFrames++;
                        Console.WriteLine($"[NoteStyle] Using note frame for receptor lane {lane}");
                    }
                }
            }
            
            Console.WriteLine($"[NoteStyle] Loaded {foundReceptorFrames}/4 receptor frames");

            // ── Hold texture and frames (optional) ────────────────────────────
            string[] holdCandidates = { "NOTE_hold_FMM.png", "NOTE_hold_assets.png", "hold.png" };
            foreach (var c in holdCandidates)
            {
                string p = Path.Combine(folderPath, c);
                if (!File.Exists(p)) p = Path.Combine(folderPath, "shared", "images", c);
                if (File.Exists(p))
                {
                    using var fs = File.OpenRead(p);
                    style.HoldTexture = Texture2D.FromStream(gd, fs);
                    break;
                }
            }
            
            // Load hold frames from atlas (use config if available)
            // For Codename Engine, ALWAYS load from atlas even if HoldTexture exists
            if (noteAtlas != null && (style.IsCodenameEngine || style.HoldTexture == null))
            {
                bool hasHoldFrames = false;
                string[] dirs = { "left", "down", "up", "right" };
                
                // For Codename Engine, always use fallback detection regardless of config
                if (style.IsCodenameEngine || config == null)
                {
                    // Fallback detection
                    Console.WriteLine($"[NoteStyle] Loading Codename hold frames from atlas...");
                    string[] holdColors = { "purple", "blue", "green", "red" };
                    for (int i = 0; i < 4; i++)
                    {
                        style.HoldPieceFrames[i] = noteAtlas.GetFirstFrame(holdColors[i] + " hold piece")
                                                ?? noteAtlas.GetFirstFrame(holdColors[i] + "holdpiece")
                                                ?? noteAtlas.GetFirstFrame(holdColors[i] + " hold");
                        
                        style.HoldEndFrames[i] = noteAtlas.GetFirstFrame(holdColors[i] + " hold end")
                                              ?? noteAtlas.GetFirstFrame(holdColors[i] + "holdend")
                                              ?? noteAtlas.GetFirstFrame(holdColors[i] + " end hold");
                        
                        if (i == 0 && style.HoldEndFrames[i] == null)
                            style.HoldEndFrames[i] = noteAtlas.GetFirstFrame("pruple end hold");
                        
                        Console.WriteLine($"  {holdColors[i]}: piece={style.HoldPieceFrames[i]?.Name ?? "NULL"}, end={style.HoldEndFrames[i]?.Name ?? "NULL"}");
                        
                        if (style.HoldPieceFrames[i] != null || style.HoldEndFrames[i] != null)
                            hasHoldFrames = true;
                    }
                    Console.WriteLine($"[NoteStyle] hasHoldFrames = {hasHoldFrames}");
                }
                else if (config != null)
                {
                    // Use config mappings
                    for (int i = 0; i < 4; i++)
                    {
                        string dir = dirs[i];
                        if (!config.Holds.TryGetValue(dir, out var hold)) continue;
                        
                        if (!string.IsNullOrEmpty(hold.Piece))
                        {
                            style.HoldPieceFrames[i] = noteAtlas.GetFirstFrame(hold.Piece);
                            if (style.HoldPieceFrames[i] != null) hasHoldFrames = true;
                        }
                        
                        if (!string.IsNullOrEmpty(hold.End))
                        {
                            style.HoldEndFrames[i] = noteAtlas.GetFirstFrame(hold.End);
                            if (style.HoldEndFrames[i] != null) hasHoldFrames = true;
                        }
                    }
                }
                
                if (hasHoldFrames)
                    style.HoldTexture = noteTex;
            }

            // ── Optional skin.json — per-skin configuration ───────────────────
            // Supports: { "fps": [12, 24, 24, 12], "noteScale": 0.7, "receptorScale": 0.7, "colorizeByLane": true }
            // fps array order: [static, press, confirm, confirmHold]
            string skinJson = Path.Combine(folderPath, "skin.json");
            if (File.Exists(skinJson))
            {
                try
                {
                    var doc2 = System.Text.Json.JsonDocument.Parse(File.ReadAllText(skinJson));
                    var root2 = doc2.RootElement;
                    if (root2.TryGetProperty("fps", out var fpsArr) && fpsArr.ValueKind == System.Text.Json.JsonValueKind.Array)
                    {
                        var fps = new float[4];
                        // Fill with defaults first
                        for (int i = 0; i < 4; i++) fps[i] = style.StateFps[i];
                        int idx = 0;
                        foreach (var v in fpsArr.EnumerateArray())
                        {
                            if (idx >= 4) break;
                            fps[idx++] = v.GetSingle();
                        }
                        style.StateFps = fps;
                    }
                    if (root2.TryGetProperty("noteScale", out var ns))
                        style.NoteScale = ns.GetSingle();
                    if (root2.TryGetProperty("receptorScale", out var rs))
                        style.ReceptorScale = rs.GetSingle();
                    if (root2.TryGetProperty("colorizeByLane", out var cbl))
                        style.ColorizeByLane = cbl.GetBoolean();

                    // Tint colors for skin types: [r, g, b] arrays (0-255)
                    if (root2.TryGetProperty("tintDamage", out var td) && td.ValueKind == System.Text.Json.JsonValueKind.Array)
                        style.TintDamage = ParseColorArray(td);
                    if (root2.TryGetProperty("tintInstakill", out var ti) && ti.ValueKind == System.Text.Json.JsonValueKind.Array)
                        style.TintInstakill = ParseColorArray(ti);
                    if (root2.TryGetProperty("tintHeal", out var th) && th.ValueKind == System.Text.Json.JsonValueKind.Array)
                        style.TintHeal = ParseColorArray(th);
                }
                catch (Exception exJson)
                {
                    Console.Error.WriteLine($"[NoteStyle] skin.json parse error in {folderPath}: {exJson.Message}");
                }
            }
            
            // ── Apply config.json settings (colorizeByLane) ───────────────────
            if (config != null)
            {
                style.ColorizeByLane = config.ColorizeByLane;
                style.HoldEndCapMode = config.HoldEndCapMode;
                Console.WriteLine($"[NoteStyle] ColorizeByLane: {style.ColorizeByLane}, HoldEndCapMode: {style.HoldEndCapMode}");
            }

            // ── Optional funkin.json — FMM v1.1 holdNoteCover support ──────────
            // Check for Assets/data/notestyles/funkin.json or just funkin.json
            string[] jsonPaths = {
                Path.Combine(folderPath, "Assets", "data", "notestyles", "funkin.json"),
                Path.Combine(folderPath, "funkin.json")
            };
            
            foreach (var jsonPath in jsonPaths)
            {
                if (!File.Exists(jsonPath)) continue;
                
                try
                {
                    var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(jsonPath));
                    var root = doc.RootElement;
                    
                    // Load holdNoteCover if it exists
                    if (root.TryGetProperty("assets", out var assets) &&
                        assets.TryGetProperty("holdNoteCover", out var holdCover) &&
                        holdCover.TryGetProperty("data", out var coverData))
                    {
                        string[] dirs = { "left", "down", "up", "right" };
                        for (int i = 0; i < 4; i++)
                        {
                            if (!coverData.TryGetProperty(dirs[i], out var dirData)) continue;
                            
                            // Get assetPath for this direction
                            string? assetPath = null;
                            if (dirData.TryGetProperty("assetPath", out var ap))
                                assetPath = ap.GetString();
                            
                            // If no assetPath, skip
                            if (string.IsNullOrEmpty(assetPath)) continue;
                            
                            // Load the PNG/XML for this hold cover
                            // Format: "shared:holdCoverPurple" → "shared/images/holdCoverPurple.png"
                            string[] parts = assetPath.Split(':');
                            string relativePath = parts.Length > 1 ? parts[1] : parts[0];
                            
                            string coverPng = Path.Combine(folderPath, "shared", "images", relativePath + ".png");
                            string coverXml = Path.ChangeExtension(coverPng, ".xml");
                            
                            if (!File.Exists(coverPng) || !File.Exists(coverXml))
                            {
                                // Try without "shared/images" prefix
                                coverPng = Path.Combine(folderPath, relativePath + ".png");
                                coverXml = Path.ChangeExtension(coverPng, ".xml");
                            }
                            
                            if (!File.Exists(coverPng) || !File.Exists(coverXml)) continue;
                            
                            // Load texture and atlas
                            Texture2D coverTex;
                            using (var fs = File.OpenRead(coverPng))
                                coverTex = Texture2D.FromStream(gd, fs);
                            var coverAtlas = new TextureAtlas(coverTex, File.ReadAllText(coverXml));
                            
                            // Load start/hold/end frames
                            if (dirData.TryGetProperty("start", out var startData) &&
                                startData.TryGetProperty("prefix", out var startPrefix))
                            {
                                style.HoldCoverStart[i] = coverAtlas.GetFirstFrame(startPrefix.GetString() ?? "");
                            }
                            
                            if (dirData.TryGetProperty("hold", out var holdData) &&
                                holdData.TryGetProperty("prefix", out var holdPrefix))
                            {
                                style.HoldCoverHold[i] = coverAtlas.GetFirstFrame(holdPrefix.GetString() ?? "");
                            }
                            
                            if (dirData.TryGetProperty("end", out var endData) &&
                                endData.TryGetProperty("prefix", out var endPrefix))
                            {
                                style.HoldCoverEnd[i] = coverAtlas.GetFirstFrame(endPrefix.GetString() ?? "");
                            }
                        }
                    }
                }
                catch (Exception exJson)
                {
                    Console.Error.WriteLine($"[NoteStyle] funkin.json parse error in {jsonPath}: {exJson.Message}");
                }
                
                break; // Only try first existing JSON
            }

            return style;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"[NoteStyle] Failed to load from {folderPath}: {ex.Message}");
            return null;
        }
    }

    /// <summary>
    /// Returns all available note style names: "Default" + any folder in notestyles/.
    /// A folder is valid if it has at least one PNG and one XML file.
    /// </summary>
    public static List<string> GetAvailableStyles(string assetsRoot)
    {
        var styles = new List<string> { "Default" };
        string stylesDir = PlatformPaths.GetNoteStylesPath();
        if (Directory.Exists(stylesDir))
        {
            foreach (var dir in Directory.GetDirectories(stylesDir))
            {
                string name = Path.GetFileName(dir);
                if (string.IsNullOrEmpty(name)) continue;
                // Accept any folder that has at least one PNG and one XML
                bool hasPng = Directory.GetFiles(dir, "*.png").Length > 0;
                bool hasXml = Directory.GetFiles(dir, "*.xml").Length > 0;
                if (hasPng && hasXml)
                    styles.Add(name);
            }
        }
        return styles;
    }

    /// <summary>
    /// Loads a style by name. "Default" loads from assetsRoot, others from notestyles/<name>/.
    /// </summary>
    public static NoteStyle? LoadByName(string name, string assetsRoot, GraphicsDevice gd)
    {
        if (name == "Default" || string.IsNullOrEmpty(name))
            return LoadFromFolder(assetsRoot, gd);

        string stylesDir = PlatformPaths.GetNoteStylesPath();
        string skinDir   = Path.Combine(stylesDir, name);
        
        // Try to load from named subfolder first
        if (Directory.Exists(skinDir))
        {
            var style = LoadFromFolder(skinDir, gd);
            if (style != null) return style;
        }
        
        // ANDROID FIX: Also try to load directly from notestyles/ root
        // Users may place files there instead of in a subfolder
        if (Directory.Exists(stylesDir))
        {
            Console.WriteLine($"[NoteStyle] '{name}' subfolder not found, searching in notestyles/ root...");
            var style = LoadFromFolder(stylesDir, gd);
            if (style != null)
            {
                Console.WriteLine($"[NoteStyle] Found note style in notestyles/ root!");
                return style;
            }
        }
        
        // Fallback to default
        return LoadFromFolder(assetsRoot, gd);
    }

    /// <summary>
    /// Detects if an XML contains both notes and receptors in one file (Codename/Haunted style).
    /// Checks for presence of receptor frames like "down press", "down confirm", "left confirm", etc.
    /// </summary>
    private static bool DetectUnifiedXML(string xmlContent)
    {
        // Look for typical Codename Engine receptor frame names
        string[] receptorIndicators = {
            "down press",
            "down confirm", 
            "left press",
            "left confirm",
            "up press",
            "up confirm",
            "right press",
            "right confirm"
        };
        
        foreach (var indicator in receptorIndicators)
        {
            if (xmlContent.Contains(indicator, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }
        
        return false;
    }

    private static Microsoft.Xna.Framework.Color ParseColorArray(System.Text.Json.JsonElement arr)
    {
        int r = 255, g = 255, b = 255;
        int idx = 0;
        foreach (var v in arr.EnumerateArray())
        {
            int val = v.ValueKind == System.Text.Json.JsonValueKind.Number ? (int)v.GetDouble() : 255;
            if      (idx == 0) r = val;
            else if (idx == 1) g = val;
            else if (idx == 2) b = val;
            idx++;
        }
        return new Microsoft.Xna.Framework.Color(r, g, b);
    }
}
